import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const RateUser = () => {
  const [usersToRate, setUsersToRate] = useState([]);

  useEffect(() => {
    const userId = sessionStorage.getItem("userId");
    if (userId) {
      fetch(`${API_BASE_URL}/api/ratings/partners/${userId}`)
        .then((res) => res.json())
        .then((data) => {
          if (Array.isArray(data)) {
            setUsersToRate(data);
          } else {
            setUsersToRate([]);
          }
        })
        .catch((err) => {
          console.error("Failed to load users to rate:", err);
          setUsersToRate([]);
        });
    }
  }, []);

  const handleRate = async (ratedUserId, rating) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/ratings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          rater_id: sessionStorage.getItem("userId"),
          rated_id: ratedUserId,
          rating: rating,
        }),
      });

      if (res.ok) {
        alert("Rating submitted!");
      } else {
        alert("Failed to submit rating.");
      }
    } catch (err) {
      console.error("Error submitting rating:", err);
      alert("Something went wrong.");
    }
  };

  return (
    <div>
      <Navbar />
      <main className="rate-user-wrapper" style={{ padding: "32px 48px", minHeight: "80vh" }}>
        <h2 style={{ textAlign: "center", marginBottom: "32px" }}>Rate Other Users</h2>

        {usersToRate.length === 0 ? (
          <p style={{ textAlign: "center" }}>No users to rate yet.</p>
        ) : (
          <div className="rating-list" style={{ display: "flex", flexWrap: "wrap", gap: "24px", justifyContent: "center" }}>
            {usersToRate.map((user) => (
              <div className="rate-card" key={user.id} style={{
                background: "#fff",
                borderRadius: "12px",
                padding: "24px",
                width: "300px",
                boxShadow: "0 4px 12px rgba(0, 0, 0, 0.05)"
              }}>
                <h4>{user.username}</h4>
                <p>{user.email}</p>
                <div className="rating-buttons" style={{ marginTop: "10px" }}>
                  {[1, 2, 3, 4, 5].map((n) => (
                    <button
                      key={n}
                      onClick={() => handleRate(user.id, n)}
                      style={{
                        margin: "5px",
                        padding: "6px 10px",
                        backgroundColor: "#facc15",
                        border: "none",
                        borderRadius: "6px",
                        cursor: "pointer"
                      }}
                    >
                      {n}⭐
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default RateUser;
